def minEatingSpeed(piles, h):
    # Helper function to determine if Koko can finish with speed k
    def canFinish(k):
        hours = 0
        for pile in piles:
            # Calculate hours by using ceiling division for each pile
            hours += (pile + k - 1) // k
        return hours <= h

    left, right = 1, max(piles)  # Speed is between 1 and the max pile element
    while left < right:
        mid = (left + right) // 2  # Candidate eating speed
        if canFinish(mid):
            right = mid  # Try finding a smaller valid speed
        else:
            left = mid + 1  # Increase the speed because mid is too slow
    return left

